"""
Enable direct MAVLink communication using libmav from a server component.

 Unlike MavlinkDirect, this does not require a discovered system: it sends from
 the local server component, which makes it suitable for broadcasting messages
 (e.g. as an autopilot or custom component) without a connected counterpart.
"""

import asyncio
from typing import AsyncGenerator
from mavsdk.plugins.mavlink_direct_server import (
    MavlinkDirectServer,
    MavlinkDirectServerResult,
    MavlinkDirectServerError,
    MavlinkMessage,
)


class MavlinkDirectServerAsync:
    """
       Enable direct MAVLink communication using libmav from a server component.

    Unlike MavlinkDirect, this does not require a discovered system: it sends from
    the local server component, which makes it suitable for broadcasting messages
    (e.g. as an autopilot or custom component) without a connected counterpart.

       Async wrapper around :class:`MavlinkDirectServer` that mirrors the gRPC-based
       asyncio API while using the ctypes-based C library directly.
    """

    def __init__(self, server_component):
        self._plugin = MavlinkDirectServer(server_component)

    async def send_message(self, message):
        """
               Send a MAVLink message directly.

        This allows sending any MAVLink message with full control over the message content.
        Leave target_system_id and target_component_id at 0 to broadcast.

               Parameters
               ----------
               message : MavlinkMessage
               Raises
               ------
               MavlinkDirectServerError
                   If the request fails. The error contains the reason for the failure.
        """
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(
            None, lambda: self._plugin.send_message(message)
        )

    async def subscribe_message(
        self, message_name
    ) -> AsyncGenerator[MavlinkMessage, None]:
        """
               Subscribe to incoming MAVLink messages.

        This provides direct access to incoming MAVLink messages. Use an empty string
        in message_name to subscribe to all messages, or specify a message name
        (e.g., "HEARTBEAT") to filter for specific message types. Unlike the
        MavlinkDirect (client) plugin, this is not scoped to a single system: it
        receives matching messages from all systems.

               Yields
               ------
               mavlink_message : MavlinkMessage
                    The next update
        """
        loop = asyncio.get_running_loop()
        queue: asyncio.Queue = asyncio.Queue()

        def callback(data, _user_data):
            loop.call_soon_threadsafe(queue.put_nowait, data)

        handle = self._plugin.subscribe_message(message_name, callback)
        try:
            while True:
                yield await queue.get()
        finally:
            self._plugin.unsubscribe_message(handle)

    async def load_custom_xml(self, xml_content):
        """
               Load custom MAVLink message definitions from XML.

        This allows loading custom MAVLink message definitions at runtime,
        extending the available message types beyond the built-in definitions.

               Parameters
               ----------
               xml_content : str
               Raises
               ------
               MavlinkDirectServerError
                   If the request fails. The error contains the reason for the failure.
        """
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(
            None, lambda: self._plugin.load_custom_xml(xml_content)
        )

    async def subscribe_command(self, command) -> AsyncGenerator[MavlinkMessage, None]:
        """
               Subscribe to incoming commands with a given command ID.

        Delivers COMMAND_LONG and COMMAND_INT messages with this command ID that are
        addressed to this server component; check message_name to see which one it is.

        While subscribed, MAVSDK does not ack the command itself, so every command
        received must be answered by sending a COMMAND_ACK with SendMessage, addressed
        to the sender (system_id/component_id of the received command) and with
        "command" set to the command ID. For a command that takes a while, send acks
        with MAV_RESULT_IN_PROGRESS and "progress" in percent (255 if unknown) about
        once per second while it runs, so the sender knows it is still going, then
        the final result.

        The sender may retransmit the command if the ack is lost, so the same command
        can arrive more than once.

               Yields
               ------
               mavlink_message : MavlinkMessage
                    The next update
        """
        loop = asyncio.get_running_loop()
        queue: asyncio.Queue = asyncio.Queue()

        def callback(data, _user_data):
            loop.call_soon_threadsafe(queue.put_nowait, data)

        handle = self._plugin.subscribe_command(command, callback)
        try:
            while True:
                yield await queue.get()
        finally:
            self._plugin.unsubscribe_command(handle)

    def destroy(self):
        self._plugin.destroy()

    def __del__(self):
        self.destroy()
